"""Offline interactive dashboard: every table/plot reads the shared model report."""

import json
from html import escape


def page(report):
    from .exports import historical_html

    payload = (
        json.dumps(report, ensure_ascii=False)
        .replace("<", "\\u003c")
        .replace(">", "\\u003e")
        .replace("&", "\\u0026")
    )
    document = (
        '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Acquisition financing simulator</title><style>\nbody{font:15px/1.5 Arial,sans-serif;color:#172c43;background:#f5f7fa;margin:0}main{max-width:1400px;margin:auto;padding:28px}\nh1{font-size:28px;margin:0}h2{font-size:20px;margin-top:28px}h3{font-size:16px}.muted{color:#526477}.status{background:#fff2ee;border-left:4px solid #ad321c;padding:12px}\n.controls,.card{background:white;padding:16px;margin:12px 0;border:1px solid #dbe2e9;border-radius:4px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\nlabel{margin-right:16px;display:inline-block}select,input,button{font:inherit;padding:7px;border:1px solid #8295aa;border-radius:3px}input[type=number]{width:100px}button{background:#193f68;color:white;cursor:pointer}\ntable{border-collapse:collapse;width:100%;background:white;font-size:13px}th,td{padding:9px;border-bottom:1px solid #e0e5eb;text-align:right;vertical-align:top}th{background:#203d5b;color:white}th:first-child,td:first-child{text-align:left}\n.scroll{overflow:auto;max-height:550px}.bad{color:#ad321c;font-weight:bold}.good{color:#172c43}svg{width:100%;height:220px;background:white}details{margin:16px 0}summary{cursor:pointer;font-weight:bold}.metric{font-size:25px;font-weight:bold}\n@media(max-width:800px){.grid{grid-template-columns:1fr}main{padding:15px}}a{color:#175b98}\n</style></head><body><main><h1>Acquisition Financing &amp; Debt Capacity Simulator</h1>\n<p id="scope" class="muted"></p><p id="status" class="status" role="alert"></p>\n<p id="tracks"></p><p id="historicalPreference"></p>\n<form class="controls" method="get"><label>Cash floor <input type="number" name="cash_floor" id="cash_floor" min="0" step="50"></label>\n<label>Maximum leverage <input type="number" name="max_leverage" id="max_leverage" min="0" step="0.1"></label>\n<label>Minimum coverage <input type="number" name="min_coverage" id="min_coverage" min="0" step="0.1"></label><button type="submit">Recalculate on live server</button>\n<p class="muted">These are analyst thresholds. Saved HTML supports scenario selection; use the live server or CLI to recalculate assumptions.</p></form>\n<div class="controls"><label>Structure <select id="structure"></select></label><label>Scenario <select id="scenario"></select></label>\n<span id="feasible"></span></div><div class="grid"><div class="card">Minimum cash<div class="metric" id="minimum"></div></div><div class="card">Five-year interest<div class="metric" id="interest"></div></div><div class="card">Ownership dilution<div class="metric" id="dilution"></div></div></div>\n<div class="grid"><div class="card"><h3>Cash and reserve (USD millions)</h3><svg id="cashChart" viewBox="0 0 420 220" role="img" aria-label="Cash and reserve"></svg></div>\n<div class="card"><h3>Financial debt (USD millions)</h3><svg id="debtChart" viewBox="0 0 420 220" role="img" aria-label="Financial debt"></svg></div>\n<div class="card"><h3>Conditional base assessment</h3><p id="recommendation"></p></div></div>\n<h2>Sources and uses / closing bridge</h2><div id="opening" class="scroll"></div>\n<h2>Five-year operating and liquidity model</h2><div id="annual" class="scroll"></div>\n<details><summary>Company operating forecasts and debt instruments</summary><div id="companies" class="scroll"></div><div id="debt" class="scroll"></div></details>\n<h2>Debt capacity and reverse stress</h2><div id="capacity"></div><div id="reverse"></div>\n<details><summary>Capacity grid and threshold/pricing sensitivities</summary><div id="grid" class="scroll"></div><div id="sensitivity" class="scroll"></div></details>\n<h2>First two years of illustrative quarterly liquidity</h2><p>Quarterly seasonality and trailing seeds are synthetic. Quarterly financing differs from annual settlement timing.</p><div id="quarters" class="scroll"></div>\n<h2>Evidence and verified historical observations</h2><p>Verified observations below are separate from the fictional model above. Missing evidence remains missing even when it is not a recommendation blocker.</p>\n<label>Filter evidence <input id="filter" type="search"></label><div id="evidence" class="scroll"></div>\n<p id="trace" class="muted"></p></main><script id="data" type="application/json">'
        + payload
        + "</script><script>\nconst R=JSON.parse(document.getElementById('data').textContent),M=R.model;\nconst E=id=>document.getElementById(id),f=n=>n===null||n===undefined?'n.a.':typeof n==='number'?n.toLocaleString('en-US',{maximumFractionDigits:2}):String(n);\nfunction table(id,heads,rows){const t=document.createElement('table'),head=t.createTHead().insertRow();heads.forEach(h=>{let th=document.createElement('th');th.textContent=h;head.append(th)});let b=t.createTBody();rows.forEach(row=>{let tr=b.insertRow();row.forEach(x=>{let td=tr.insertCell();td.textContent=f(x)})});E(id).replaceChildren(t)}\nfunction chart(id,values,floor){const ns='http://www.w3.org/2000/svg',s=E(id);s.replaceChildren();let lo=Math.min(0,...values),hi=Math.max(1,...values,floor||0);const y=v=>185-(v-lo)/(hi-lo)*160;let line=document.createElementNS(ns,'polyline');line.setAttribute('points',values.map((v,i)=>`${40+i*78},${y(v)}`).join(' '));line.setAttribute('fill','none');line.setAttribute('stroke','#246aa4');line.setAttribute('stroke-width','3');s.append(line);values.forEach((v,i)=>{let a=document.createElementNS(ns,'text');a.setAttribute('x',25+i*78);a.setAttribute('y',210);a.textContent='Y'+(i+1);s.append(a);let t=document.createElementNS(ns,'text');t.setAttribute('x',25+i*78);t.setAttribute('y',Math.max(15,y(v)-8));t.setAttribute('font-size','11');t.textContent=f(v);s.append(t)});if(floor!==undefined){let a=document.createElementNS(ns,'line');a.setAttribute('x1',30);a.setAttribute('x2',365);a.setAttribute('y1',y(floor));a.setAttribute('y2',y(floor));a.setAttribute('stroke','#ae5f25');a.setAttribute('stroke-dasharray','5');s.append(a)}}\nE('status').textContent=R.recommendation_status;E('tracks').textContent='Engineering: '+R.engineering_status+' | Historical analysis: '+(R.historical_analysis_complete?'Complete with qualifications':'Blocked / incomplete');\nE('historicalPreference').textContent='Actual-company preference: '+(R.preferred_structure||'None');\nE('scope').textContent=M.config.label+' | USD millions | Five full post-close model years';\nE('trace').textContent='Input '+R.config_id+' | Code '+M.code_id+' | Run '+(R.run_id||'not persisted');\n['cash_floor','max_leverage','min_coverage'].forEach(k=>E(k).value=M.config.policy[k]);\nconst structures=[...new Set(M.comparisons.map(r=>r.structure))],scenarios=[...new Set(M.comparisons.map(r=>r.scenario))];\nfor(const [id,options] of [['structure',structures],['scenario',scenarios]])options.forEach(v=>{let o=document.createElement('option');o.value=v;o.textContent=v;E(id).append(o)});\nE('recommendation').textContent=M.recommendation.scope+': '+M.recommendation.narrative;\nfunction refresh(){let r=M.comparisons.find(x=>x.structure===E('structure').value&&x.scenario===E('scenario').value),o=r.opening;\nE('feasible').textContent=r.feasible?'Passes selected analytical constraints':'Breach: '+r.breaches.map(b=>b.constraint+' in period '+b.period).slice(0,3).join(', ');E('feasible').className=r.feasible?'good':'bad';\nE('minimum').textContent=f(r.min_cash);E('interest').textContent=f(r.total_interest);E('dilution').textContent=f(o.ownership_dilution*100)+'%';chart('cashChart',r.years.map(a=>a.closing_cash),M.config.policy.cash_floor);chart('debtChart',r.years.map(a=>a.closing_debt));\ntable('opening',['Cash uses / financing','USD millions'],['cash_purchase','required_debt_repayment','transaction_fees','financing_fees','cash_uses','cash_contribution','acquisition_borrowing','borrowing_for_refinancing_and_fees','total_new_borrowing','retained_debt','opening_cash','opening_debt','noncash_consideration','unavailable_target_cash','sources_uses_difference'].map(k=>[k.replaceAll('_',' '),o[k]]));\ntable('annual',['Year','Revenue','EBITDA','Cash tax','Capex','Change NWC','Interest','Cash','Debt','Leverage','Coverage','Rent coverage','Maturity gap'],r.years.map(a=>[a.year,a.revenue,a.ebitda,a.tax,a.capex,a.delta_nwc,a.interest,a.closing_cash,a.closing_debt,a.net_leverage,a.coverage,a.rent_inclusive_coverage,a.maturity_gap]));\ntable('companies',['Company','Year','Revenue','EBITDA','D&A','EBIT','Inventory','Receivables','Payables'],r.company_forecasts.map(a=>[a.company,a.year,a.revenue,a.ebitda,a.da,a.ebit,a.inventory,a.receivables,a.payables]));\ntable('debt',['Instrument','Year','Opening','Rate','Interest','Mandatory due','Paid','Optional','New draw','Refinanced','Closing'],r.debt_schedule.map(d=>[d.instrument,d.year,d.opening_principal,(d.rate*100).toFixed(2)+'%',d.interest,d.mandatory_due,d.mandatory_paid,d.optional_paid,d.draw,d.refinanced,d.closing_principal]));\nlet c=M.capacity[r.structure],v=M.reverse_stress[r.structure];table('capacity',['Base annual capacity','Value'],[['Maximum acquisition borrowing',c.maximum_acquisition_borrowing],['Residual analytical equity',c.residual_analytical_equity],['Eligible acquisition uses',c.eligible_acquisition_uses],['Limited by funding needs',c.funding_limited],['Limiting constraint',JSON.stringify(c.limiting_constraint)],['Resolution',c.boundary_resolution],['Disconnected feasible ranges',c.disconnected]]);\ntable('reverse',['Base reverse stress','Value'],[['Status',v.status],['Revenue decline at first breach',v.revenue_decline===null?null:v.revenue_decline*100+'%'],['Failing constraint/period',JSON.stringify(v.failing||{})]]);\ntable('grid',['Acquisition borrowing','Feasible','First breach'],c.grid.map(x=>[x.borrowing,x.feasible,JSON.stringify(x.first_breach)]));\ntable('sensitivity',['Cash-first sensitivity','Capacity','Residual equity','Limiting constraint'],M.sensitivities.map(x=>[x.label,x.maximum_acquisition_borrowing,x.residual_analytical_equity,JSON.stringify(x.limiting_constraint)]));\nlet q=M.quarterly.find(x=>x.structure===r.structure);table('quarters',['Base year','Quarter','EBITDA','Inventory','Change NWC','Cash','Debt','TTM coverage','Gap'],q?q.periods.filter(x=>x.year<=2).map(a=>[a.year,a.quarter,a.ebitda,a.inventory,a.delta_nwc,a.closing_cash,a.closing_debt,a.coverage,a.maturity_gap]):[])}\nfunction evidence(){let needle=E('filter').value.toLowerCase();table('evidence',['Input','Value','Classification','Blocks recommendation','Materiality','Resolution'],R.evidence.rows.filter(x=>JSON.stringify(x).toLowerCase().includes(needle)).map(x=>[x.key,x.value===null?'Missing':typeof x.value==='object'?JSON.stringify(x.value):String(x.value),x.classification,x.recommendation_blocking,x.materiality_reason,x.resolution]))}\nE('structure').onchange=refresh;E('scenario').onchange=refresh;E('filter').oninput=evidence;refresh();evidence();\n</script></body></html>"
    )
    return document.replace("</main>", historical_html(report) + "</main>")


